head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isurCd = "";
scwin.isurNm = "";
scwin.inputRnd = "";
scwin.displayFlag = "";
scwin.acptNo = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — setDisplay, readSbox1, readSbox2, readSbox3, readSbox4, readSync 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {

        // 초기화함수

        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05961.onpageload" });
    }}

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출).
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    scwin.isurCd = $c.data.getParameter("isurCd");
    scwin.isurNm = $c.data.getParameter("isurNm");
    scwin.inputRnd = $c.data.getParameter("inputRnd");
    scwin.displayFlag = $c.data.getParameter("displayFlag");
    scwin.acptNo = $c.data.getParameter("acptNo");
    // 화면 제어
    scwin.setDisplay();

    if(scwin.displayFlag === "U") {

    await scwin.readSbox1();
    await scwin.readSbox2();
    await scwin.readSbox3();
    await scwin.readSbox4();
    await scwin.readSync(); // 상세조회

    }

    // 컴포넌트 객체 전달
    $c.date.checkCalendarFormat("ibcDesignDd1", "yyyyMMdd");
    $c.date.checkCalendarFormat("input_CalDesignDd2", "yyyyMMdd");
    $c.date.checkCalendarFormat("inputCal_DesignDd3", "yyyyMMdd");
    $c.date.checkCalendarFormat("iptCal_designDd4", "yyyyMMdd");

    // 날짜 포맷 검증 추가
    $c.date.compareFromToDate(inpuCal_ValidStrtDd3, inputCal_ValidEndDd1, ["유효기간 시작일자", "유효기간 종료일자"], "yyyyMMdd");
    $c.date.compareFromToDate(iptCal_ValidStrtDd2, iptCal_ValidEndDd2, ["유효기간 시작일자", "유효기간 종료일자"], "yyyyMMdd");
    $c.date.compareFromToDate(iptCal_ValidStrtDd3, iptCal_ValidEndDd3, ["유효기간 시작일자", "유효기간 종료일자"], "yyyyMMdd");
    $c.date.compareFromToDate(iptCal_ValidStrtDd4, iptCal_ValidEndDd4, ["유효기간 시작일자", "유효기간 종료일자"], "yyyyMMdd");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @Event
 * @name btn_Close_onclick
 * @description btn_Close_onclick event
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function (e) {
    try {
        $c.win.closeAllPopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05961.btn_Close_onclick" });
    }
};

/**
 * @method
 * @Event
 * @name sbx_SectAhthQualTpCd1_onchange
 * @description 벤처기업 인증자격 onchange event
 * @returns {void}
 * @hidden N
 */
scwin.sbx_SectAhthQualTpCd1_onchange = async function (info) {
    try {
        if(scwin.displayFlag === "U"  ) return
        await scwin.readSbox("1");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05961.sbx_SectAhthQualTpCd1_onchange" });
    }
};

