/**
 * @method
 * @name img_coSearch_onclick
 * @description 발행회사검색(팝업)호출
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_coSearch_onclick = async function (e) {
    try {
        const res = await $c.lc.popFindCorpChrg(scwin.fr_SecuGrpId);

        ibx_isurCd.setValue(res.isurCd)
        ixb_ComNm.setValue(res.comAbbrv)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05961.img_coSearch_onclick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 인증및자격관리(저장,수정) — 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_save_onclick = function (e) {
    try {
        scwin.save();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05961.btn_save_onclick" });
    }
};

/**
 * @method
 * @name mUpBtn_onclick
 * @description 파일추가
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.mUpBtn_onclick = function (e) {
    try {
        $c.util.onUploadClick(muc);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05961.mUpBtn_onclick" });
    }
};

/**
 * @method
 * @name muc_ondone
 * @description 콜백 done
 * @param {*} data 셀 값(원본 데이터)
 * @param {Object} result 통신 응답 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.muc_ondone = async function (data,result) {
    try {
        let sText = "";
        if(scwin.displayFlag === "C") {
        sText = "[저장]"
        } else {
        sText = "[수정]"
        }
        if(result.success){
        await $c.win.alert(sText+" 성공적으로 처리되었습니다.");
        await $c.win.closePopup();
        $c.win.getParent().scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05961.muc_ondone" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 파일삭제 UI에서만 삭제 됨 — 「파일삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function(e) {
    try {
            let idxArrJson = grd_fileList.getCheckedJSON("chk");
            let idxArrIndex = grd_fileList.getCheckedIndex( "chk" );
            for( let i=0;i<idxArrJson.length;i++ ) {
                const fileName = idxArrJson[i].attachFileNm;
                muc.removeFile( fileName );
            }
        dlt_FileInfoList.removeRows( idxArrIndex );
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05961.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name muc_onprogress
 * @description 업로드 끝난후 저장끝난후
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.muc_onprogress = async function (e) {

};

/**
 * @method
 * @Event
