/**
 * @method
 * @Event
 * @name grd_fileList_oncelldblclick
 * @description: 파일다운로드
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {

            if(columnId === "saveFileNm") {
                const vBzProcsNo   = dlt_FileInfoList.getCellData(rowIndex, "bzProcsNo");
                const vDisclsDocNo =  dlt_FileInfoList.getCellData(rowIndex, "disclsDocNo");
                const vAttachSeq =  dlt_FileInfoList.getCellData(rowIndex, "attachSeq");
                const vFileNm =  dlt_FileInfoList.getCellData(rowIndex, "saveFileNm");

                let gubunVal = "";
                let fileIdVal = "";

                if(vBzProcsNo !== '') {
                    gubunVal = "23";
                    fileIdVal = vBzProcsNo;
                } else if( vDisclsDocNo !== '') {
                    gubunVal = "12";
                    fileIdVal = vDisclsDocNo;
                }

                const url = "/api/listing/common/file/file-download";

                const param = {
                                gubun : gubunVal
                                ,fileId : fileIdVal
                                ,attachSeq : vAttachSeq
                            };

                $c.data.downFile(url, vFileNm, param)

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05961.grd_fileList_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @func
 * @name scwin.readSbox
 * @description 셀렉트박스조회(등록용)
 * @returns {void}
 * @hidden N
 */
scwin.readSbox = async function(val) {

    const strIndexVal = val;
    dma_searchReq.set("strIndex",strIndexVal);

    let sTarget = "";

    if(strIndexVal === "1") {
        sTarget = "dlt_SectAhthQualCd1Res=body.sectAuthQualCdDto, dlt_SectAhthInstCd1Res=body.sectAuthInstCdDto";
    } else if ( strIndexVal === "2") {
        sTarget = "dlt_SectAhthQualCd2Res=body.sectAuthQualCdDto, dlt_SectAhthInstCd2Res=body.sectAuthInstCdDto";
    } else if ( strIndexVal === "3") {
        sTarget = "dlt_SectAhthQualCd3Res=body.sectAuthQualCdDto, dlt_SectAhthInstCd3Res=body.sectAuthInstCdDto";
    } else {
        sTarget = "dlt_SectAhthQualCd4Res=body.sectAuthQualCdDto, dlt_SectAhthInstCd4Res=body.sectAuthInstCdDto";
    }

    const sbmOptions = {
        id : "sbm_SectAhthQualCd",
        method: "get",
        ref: "dma_searchReq",
        action : "/api/listing/lstmgt/sect-authqual/combo-list-qualcd",
        target : sTarget,
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        if(strIndexVal === "1") {
            dlt_SectAhthQualCd1Res.insertRow(0);
            dlt_SectAhthInstCd1Res.insertRow(0);
            sbx_SectAhthQualCd1.setNodeSet("data:" + "dlt_SectAhthQualCd1Res","text","value");
            sbx_SectAhthInstCd1.setNodeSet("data:" + "dlt_SectAhthInstCd1Res","text","value");
        } else if ( strIndexVal === "2") {
            dlt_SectAhthQualCd2Res.insertRow(0);
            dlt_SectAhthInstCd2Res.insertRow(0);
            sbx_SectAhthQualCd2.setNodeSet("data:" + "dlt_SectAhthQualCd2Res","text","value");
            sbx_SectAhthInstCd2.setNodeSet("data:" + "dlt_SectAhthInstCd2Res","text","value");
        } else if ( strIndexVal === "3") {
            dlt_SectAhthQualCd3Res.insertRow(0);
            dlt_SectAhthInstCd3Res.insertRow(0);
            sbx_SectAhthQualCd3.setNodeSet("data:" + "dlt_SectAhthQualCd3Res","text","value");
            sbx_SectAhthInstCd3.setNodeSet("data:" + "dlt_SectAhthInstCd3Res","text","value");
        } else {
            dlt_SectAhthQualCd4Res.insertRow(0);
            dlt_SectAhthInstCd4Res.insertRow(0);
            sbx_SectAhthQualCd4.setNodeSet("data:" + "dlt_SectAhthQualCd4Res","text","value");
            sbx_SectAhthInstCd4.setNodeSet("data:" + "dlt_SectAhthInstCd4Res","text","value");
        }
    }

}

