        target : "dlt_SectAhthQualCd1Res=body.sectAuthQualCdDto, dlt_SectAhthInstCd1Res=body.sectAuthInstCdDto",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
            dlt_SectAhthQualCd1Res.insertRow(0);
            dlt_SectAhthInstCd1Res.insertRow(0);

            sbx_SectAhthQualCd1.setNodeSet("data:" + "dlt_SectAhthQualCd1Res","text","value");
