/**
 * @method
 * @func
 * @name scwin.readSync
 * @description 상세조회
 * @returns {void}
 * @hidden N
 */
scwin.readSync = async function() {

    dma_searchDetailReq.set("isurCd",scwin.isurCd);
    dma_searchDetailReq.set("inputRnd",scwin.inputRnd);
    dma_searchDetailReq.set("acptNo",scwin.acptNo);
    dma_searchDetailReq.set("bzProcsNo",scwin.isurCd+scwin.lpad(scwin.inputRnd));

    const sbmOptions = {
        id : "sbm_authqualDetailView",
        action : "/api/listing/lstmgt/sect-authqual/select-one-authqual",
        method : "get",
        ref : "dma_searchDetailReq",
        target : "dma_sectAuthQualInfoReqRes=body.sectAuthQualInfoDto, dlt_FileInfoList=body.sectAuthQualFileDto",
        isProcessMsg : true
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success === true) {

    }
}

/**
 * @method
 * @name selectCallback
 * @description 파일업로드시 파일정보 dataList에 세팅
 * @returns {void}
 * @hidden N
 */
scwin.selectCallback = function() {

    let fileInfos = muc.getFileInfos();
    dlt_FileInfoList.removeAll();
    dlt_FileInfoList.setBroadcast(false);
    for (i = 0; i < fileInfos.length; i++ ) {
        dlt_FileInfoList.insertRow();
        dlt_FileInfoList.setCellData(i, "attachSeq", i+1);
        dlt_FileInfoList.setCellData(i, "saveFileNm", fileInfos[i].name);
    }
    dlt_FileInfoList.setBroadcast(true, true);
    grd_fileList.setFocusedCell(0,0);
}

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setDisplay
 * @description 화면 표시 상태(활성/비활성·표시 영역)를 설정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setDisplay = async function() {

    if(scwin.displayFlag === "U") {

        // ibx_isurCd.setValue(scwin.isurCd);
        ixb_ComNm.setValue(scwin.isurNm)

        ibx_isurCd.setDisabled(true);
        img_coSearch.setDisabled(true);

        ibx_isurCd.setReadOnly(true);
        btn_fileAdd.setDisabled(true);
        btn_linedelete.setDisabled(true);

        img_coSearch.setDisabled(true);
        btn_save.setDisabled(true);

        scwin.updateUI(); // 화면제어

    } else {

        btn_update.setDisabled(true);
    }

};

/**
 * @method
 * @name updateUI
 * @description UI 수정불가값
 * @returns {void}
 * @hidden N
 */
scwin.updateUI = function() {

    ibx_isurCd.setDisabled(true)
    sbx_SectAhthQualTpCd1.setDisabled(true);
    sbx_SectAhthQualTpCd2.setDisabled(true);
    sbx_SectAhthQualTpCd3.setDisabled(true);
    sbx_SectAhthQualTpCd4.setDisabled(true);

    sbx_SectAhthQualCd1.setDisabled(true);
    sbx_SectAhthQualCd2.setDisabled(true);
    sbx_SectAhthQualCd3.setDisabled(true);
    sbx_SectAhthQualCd4.setDisabled(true);

    sbx_SectAhthInstCd1.setDisabled(true)
    sbx_SectAhthInstCd2.setDisabled(true)
    sbx_SectAhthInstCd3.setDisabled(true)
    sbx_SectAhthInstCd4.setDisabled(true)
}

/**
 * @method
 * @func
 * @name scwin.save
 * @description 저장 ,수정
 * @returns {void}
 * @hidden N
 */
scwin.save = async function() {

        if(scwin.displayFlag === "C") {

        const options = {
                validateType : "alert",
                checkType : "single",
                focus : true,
                fields : {
                    ibx_isurCd : { required : true, name : "회사명"   },
                    sbx_SectAhthQualTpCd1 : { required : true, name : "벤처기업 인증자격"   },
                    txa_Remk1 : {maxLength : 20000},
                    txa_Remk2 : {maxLength : 20000},
                    txa_Remk3 : {maxLength : 20000},
                    txa_Remk4 : {maxLength : 20000}

                }
        };

        const result = await $c.validate.validateDataCollect(grpInputForm, options);

        if (!result) {
            return false;
        }
    }

    let sText  = "";

    if(scwin.displayFlag === "C") {
        sText = "[저장]";
    } else {
        sText = "[수정]";
    }

    const rtn = await $c.win.confirm(sText+'처리 하시겠습니까?');

    if(rtn) {

