/**
 * @method
 * @name lpad
 * @description 값을 지정 자릿수(기본 9)가 되도록 왼쪽에 채움 문자(기본 '0')를 붙인다.
 * @param {String|Number} value 값
 * @param {Number} length 목표 자릿수(기본 9)
 * @param {String} padChar 채움 문자(기본 '0')
 * @returns {String} 자릿수를 맞춘 문자열
 * @hidden N
 */
scwin.lpad = function(value, length = 9, padChar = '0') {

    return String(value).padStart(length, padChar);
}
